{"task":"classify_objects","unchanged_action_limit":1100,"interface":{"execution":"Only scene, reobserve, approach, gripper. Source contains only def policy(robot,memory), no imports, classes, global, nonlocal, async, await, yield, decorators, private attributes, filesystem or network. Finite loops. All admissions use the same explicit AST contract. Returning leads to native bounded hold, not automatic success. Gripper commands persist across subsequent motion.","geometry":{"basket_release_tool_z":1.01,"gripper_tool_offset_above_contact":0.125,"minimum_contact_tool_z":0.92,"quaternion_requirement":"Normalize to unit length using arithmetic; imports unavailable","table_z":0.765,"typical_downward_quaternion":{"left":[0.613,-0.3593,0.6163,0.3392],"right":[0.3814,-0.6197,0.3785,0.572]},"world_units":"metres"},"methods":{"approach":"robot.approach(arm,position_m,quaternion_wxyz), keyword arguments only. Success returns observed state, NOT physical completion. A trusted pre-action planning rejection returns {primitive_error:"no_collision_free_path",state:...}; this call executed zero actions. Other exceptions may follow partial execution and remain fatal/uncertain.","gripper":"robot.gripper(arm="left" or "right", command=0 closed or 1 open) -> observed joints; settling only, no grasp success claim","reobserve":"robot.reobserve() -> {state: observed joint arrays}; no score","scene":"robot.scene() -> {objects: {"<category>_<positive_instance_index>": {pose:[x,y,z,w,x,y,z],dims:[x,y,z]}}, observation}; keys are strings. Examples: basket_1, watch_2, toy_car_1. Split at the last underscore; category is a string, only the final instance suffix is an integer. RGB estimates, world-frame metres; no hidden layouts or success signal."},"policy_signature":"def policy(robot, memory)","scene_object_key_contract":{"examples":{"basket_1":["basket",1],"toy_car_1":["toy_car",1],"watch_2":["watch",2]},"format":"<category>_<positive integer instance index>","identity":"Equal category strings indicate the same class; full keys identify distinct visible instances, not persistent tracking identities.","key_type":"string","parsing":"Split at the LAST underscore. Keep category as a string; only the final suffix is an integer. Do not call int() on the whole key.","scope":"Names are produced by this study's RGB adapter; examples contain no evaluation layout or success signal.","version":"study-scene-object-names/v2"},"scope":"Study-specific bounded System2 iteration using step4-qualified calibrated RGB/CuRobo primitives; not stock paper performance or a full dynamic-object collision model","semantics":"Sort visible objects by category into separate baskets; assign one basket per category, grouping identical objects together. No success signal is available from primitives.","task":"classify_objects"},"parent_source":"def policy(robot, memory):
    def normalize(q):
        n = sum(v*v for v in q) ** 0.5
        return [v/n for v in q] if n > 0.000001 else None

    quats = {
        'left': normalize([0.613, -0.3593, 0.6163, 0.3392]),
        'right': normalize([0.3814, -0.6197, 0.3785, 0.572])
    }

    def read_scene():
        data = robot.scene()
        result = []
        for key, obj in list(data.get('objects', {}).items())[:64]:
            if not isinstance(key, str) or '_' not in key or not isinstance(obj, dict):
                continue
            category, suffix = key.rsplit('_', 1)
            if not category or not suffix.isdigit() or int(suffix) < 1:
                continue
            p, d = obj.get('pose', []), obj.get('dims', [])
            if len(p) != 7 or len(d) != 3:
                continue
            values = list(p) + list(d)
            if not all(isinstance(v, (int, float)) and v == v and abs(v) < 10 for v in values):
                continue
            if not all(v > 0 for v in d):
                continue
            result.append({'category': category, 'p': list(p), 'd': list(d)})
        return result

    def inside(item, basket):
        p, b, d = item['p'], basket['p'], basket['d']
        q = normalize(b[3:7])
        if q is None:
            return False
        w, x, y, z = q
        dx, dy = p[0]-b[0], p[1]-b[1]
        lx = (1-2*(y*y+z*z))*dx + 2*(x*y+w*z)*dy
        ly = 2*(x*y-w*z)*dx + (1-2*(x*x+z*z))*dy
        return abs(lx) < d[0]/2-0.012 and abs(ly) < d[1]/2-0.012

    def move(arm, position):
        result = robot.approach(arm=arm, position_m=position, quaternion_wxyz=quats[arm])
        if isinstance(result, dict) and result.get('primitive_error'):
            if result['primitive_error'] == 'no_collision_free_path':
                return False
            raise RuntimeError('Uncertain primitive execution')
        return True

    try:
        initial = read_scene()
        baskets = sorted([o for o in initial if o['category'] == 'basket'], key=lambda o: (o['p'][0], o['p'][1]))
        items = [o for o in initial if o['category'] != 'basket']
        categories = sorted(set(o['category'] for o in items))
        if not categories or len(categories) > len(baskets) or len(baskets) > 8:
            return

        assignments, used = {}, set()
        for i, basket in enumerate(baskets):
            occupants = sorted(set(o['category'] for o in items if inside(o, basket)))
            if len(occupants) == 1 and occupants[0] not in assignments:
                assignments[occupants[0]] = i
                used.add(i)

        pending = [c for c in categories if c not in assignments]
        for unused in range(len(pending)):
            options = []
            for category in pending:
                group = [o for o in items if o['category'] == category]
                for i, basket in enumerate(baskets):
                    if i not in used:
                        cost = sum((o['p'][0]-basket['p'][0])**2 + (o['p'][1]-basket['p'][1])**2 for o in group)/len(group)
                        options.append((cost, category, i))
            if not options:
                return
            _, category, i = min(options)
            assignments[category] = i
            used.add(i)
            pending.remove(category)

        attempted = []
        for turn in range(6):
            current = read_scene()
            visible_baskets = [o for o in current if o['category'] == 'basket']
            choices = []
            for item in current:
                category = item['category']
                if category not in assignments:
                    continue
                p = item['p']
                if any(category == c and (p[0]-x)**2+(p[1]-y)**2 < 0.0016 for c, x, y in attempted):
                    continue
                anchor = baskets[assignments[category]]
                matches = [b for b in visible_baskets if (b['p'][0]-anchor['p'][0])**2+(b['p'][1]-anchor['p'][1])**2 < 0.0025]
                if len(matches) != 1:
                    continue
                basket = matches[0]
                if inside(item, basket):
                    continue
                cost = (p[0]-basket['p'][0])**2+(p[1]-basket['p'][1])**2
                choices.append((cost, item, basket))
            if not choices:
                return
            choices.sort(key=lambda entry: entry[0])
            _, item, basket = choices[0]
            x, y, z = item['p'][:3]
            bx, by = basket['p'][:2]
            attempted.append((item['category'], x, y))
            contact_z = max(0.92, z + item['d'][2]/2 + 0.125)
            clearance_z = max(1.01, contact_z + 0.045)
            if clearance_z > 1.08:
                return
            preferred = 'left' if x+bx < 0 else 'right'
            alternate = 'right' if preferred == 'left' else 'left'
            arm = None
            # Only an explicit zero-execution rejection permits this one fallback.
            for candidate in [preferred, alternate]:
                if move(candidate, [x, y, clearance_z]):
                    arm = candidate
                    break
            if arm is None:
                continue
            robot.gripper(arm=arm, command=1)
            if not move(arm, [x, y, contact_z]):
                return
            robot.gripper(arm=arm, command=0)
            if not move(arm, [x, y, clearance_z]):
                return
            # RGB height is nominal, so it cannot verify a lift or veto transport.
            destination = [bx - 0.0175, by - 0.035, 1.01]
            if abs(bx) < 0.1:
                destination = [bx + (-0.065 if arm == 'left' else 0.065), by - 0.055, 0.99]
            if not move(arm, destination):
                return
            robot.gripper(arm=arm, command=1)
    except Exception:
        # Preserve the current gripper state after uncertain physical execution.
        return
